// components/Logo.js
// ProPages logo — vector, traced from the original 25.png artwork.
// "pro" = Poppins Bold Italic, "pages" = Poppins Bold, both outlined (no font loading needed).
//
// Usage:
//   <Logo />                                   mint, glow, for dark backgrounds, 32px tall
//   <Logo colorway="periwinkle" />             original colors
//   <Logo tone="light" />                      flat, for light backgrounds (glow is dark-only)
//   <Logo mark height={40} />                  compact mark: "pro" in its bracket
//
// `height` is the height of the artwork itself. The glow spills outside that box
// without changing layout (negative margins), so a glowing and a flat logo take
// up exactly the same space in a nav.

